import React from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CartoonListRevealProps = Record<string, any>;

const CartoonListReveal: React.FC<CartoonListRevealProps> = ({
  backgroundColor = "#FF6E31", // Liquid vibrant orange
  transparentBackground = false,
  durationInSeconds = 10,
  item1Text = "🍊 Sweet Clementines",
  item2Text = "🥤 Fresh Squeezed Juice",
  item3Text = "🔥 Sunset Vibes",
  item4Text = "🥭 Mango Smoothie",
  item5Text = "🍯 Golden Honey",
  cardColor = "#FFFFFF",
  textColor = "#FFFFFF",
  accentColor = "#FFD54F", // Warm bright amber
  itemGap = 16,
}) => {
  // Load clean, cartoonish yet elegant fonts
  useFontLoader(["Fredoka One", "Plus Jakarta Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgStyle = transparentBackground
    ? "transparent"
    : `linear-gradient(135deg, ${backgroundColor} 0%, #D84315 100%)`;

  const items = [item1Text, item2Text, item3Text, item4Text, item5Text];
  
  // Layout constants optimized for 5 items
  const itemHeight = height * 0.12;
  const itemWidth = width * 0.65;
  const startY = (height - (items.length * itemHeight + (items.length - 1) * itemGap)) / 2;

  return (
    <AbsoluteFill
      style={{
        background: bgStyle,
        fontFamily: "'Fredoka One', cursive",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Liquid background shapes for refraction blur */}
      {!transparentBackground && (
        <div style={{ position: "absolute", width: "100%", height: "100%", overflow: "hidden", pointerEvents: "none" }}>
          {/* Floating Liquid Orb 1 */}
          <div
            style={{
              position: "absolute",
              width: width * 0.5,
              height: width * 0.5,
              borderRadius: "50%",
              background: "radial-gradient(circle, #FFE082 0%, rgba(255,224,130,0) 70%)",
              top: height * 0.05 + Math.sin(frame * 0.015) * 60,
              left: width * 0.1 + Math.cos(frame * 0.01) * 80,
              opacity: 0.65,
              filter: "blur(50px)",
            }}
          />
          {/* Floating Liquid Orb 2 */}
          <div
            style={{
              position: "absolute",
              width: width * 0.6,
              height: width * 0.6,
              borderRadius: "50%",
              background: "radial-gradient(circle, #FF3D00 0%, rgba(255,61,0,0) 70%)",
              bottom: height * 0.05 + Math.cos(frame * 0.012) * 50,
              right: width * 0.1 + Math.sin(frame * 0.015) * 90,
              opacity: 0.55,
              filter: "blur(60px)",
            }}
          />
        </div>
      )}

      <div style={{ position: "relative", width: "100%", height: "100%" }}>
        {items.map((text, index) => {
          // Slower, more elegant stagger delay for list items
          const delay = index * 18; 
          
          const spr = spring({
            frame: frame - delay,
            fps,
            config: { damping: 18, stiffness: 60 },
          });

          // Slower, smoother blur transition
          const blurVal = interpolate(
            frame,
            [delay, delay + 50],
            [25, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Slower opacity fade-in
          const opacityVal = interpolate(
            frame,
            [delay, delay + 18],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Calculate Y position
          const topPos = startY + index * (itemHeight + itemGap);

          // Fluid slide up transition
          const translateY = interpolate(
            spr,
            [0, 1],
            [60, 0]
          );

          const scale = interpolate(
            spr,
            [0, 1],
            [0.85, 1]
          );

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                top: topPos,
                left: (width - itemWidth) / 2,
                width: itemWidth,
                height: itemHeight,
                borderRadius: 22,
                border: "2px solid rgba(255, 255, 255, 0.45)",
                boxShadow: "0 12px 36px rgba(0, 0, 0, 0.15), inset 0 0 15px rgba(255, 255, 255, 0.25)",
                backdropFilter: "blur(24px) saturate(160%)",
                WebkitBackdropFilter: "blur(24px) saturate(160%)",
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-start",
                paddingLeft: itemWidth * 0.08,
                fontSize: itemHeight * 0.33,
                color: textColor,
                opacity: opacityVal,
                transform: `scale(${scale}) translateY(${translateY}px)`,
                filter: `blur(${blurVal}px)`,
                transition: "none",
                overflow: "hidden",
              }}
            >
              {/* Glass Card Tint Base Overlay */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  backgroundColor: cardColor,
                  opacity: 0.15,
                  zIndex: -1,
                  borderRadius: 20,
                }}
              />

              {/* Gloss sweep highlight overlay */}
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "linear-gradient(135deg, rgba(255,255,255,0.2) 0%, rgba(255,255,255,0.05) 40%, rgba(255,255,255,0) 100%)",
                  zIndex: -1,
                  borderRadius: 20,
                }}
              />

              {/* Liquid Bullet Badge */}
              <div
                style={{
                  width: itemHeight * 0.52,
                  height: itemHeight * 0.52,
                  borderRadius: "50%",
                  background: `linear-gradient(135deg, ${accentColor} 0%, #FF6D00 100%)`,
                  color: "#FFFFFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: 24,
                  border: "2px solid rgba(255, 255, 255, 0.75)",
                  fontSize: itemHeight * 0.28,
                  fontWeight: "bold",
                  boxShadow: "0 6px 14px rgba(216, 67, 21, 0.35)",
                }}
              >
                {index + 1}
              </div>
              
              {/* Item Text Container */}
              <span style={{ textShadow: "0 2px 4px rgba(0,0,0,0.15)" }}>
                {text}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default CartoonListReveal;